#!/bin/sh
# Build everything for the router into fxs/build/:
#   slic_spi_cs1.ko, mt7621_pcm_raw.ko  (OpenWrt SDK kernel modules)
#   slicctl                             (userspace SLIC control, musl/mipsel)
#   *.s16 test audio, slic-play.sh
#
# Prereqs (see the phone-port doc, "How to reproduce"):
#   - OpenWrt SDK 25.12.5 ramips/mt7621 unpacked at $SDK
#   - ./slicctl/fetch-vpapi.sh run once
#   - ./slicctl/stock_profiles.c generated by tools/extract_profiles.py
# Fails loudly: a stale .ko must never be deployed (kernel builds use -Werror,
# and a failed build would otherwise leave the previous .ko in place).
set -e
SDK=${SDK:-$HOME/owrt-sdk/openwrt-sdk-25.12.5-ramips-mt7621_gcc-14.3.0_musl.Linux-x86_64}
HERE=$(cd "$(dirname "$0")" && pwd)
OUT=$HERE/build
KVER=6.12.94
mkdir -p "$OUT"

# --- kernel modules ---
PKD=$SDK/build_dir/target-mipsel_24kc_musl/linux-ramips_mt7621/kmod-slic-mt7621/.pkgdir
# use this checkout as an OpenWrt feed (same mechanism as a src-git feed)
REPO=$(cd "$HERE/.." && pwd)
[ -f "$SDK/feeds.conf" ] || cp "$SDK/feeds.conf.default" "$SDK/feeds.conf"
# point the feed at *this* checkout (there may be more than one clone)
sed -i '/^src-link zltphone /d' "$SDK/feeds.conf"
echo "src-link zltphone $REPO" >> "$SDK/feeds.conf"
rm -f "$SDK/package/kmod-slic-mt7621" "$SDK/package/slic-fxs"	# old direct symlinks
(cd "$SDK" && ./scripts/feeds update -i zltphone >/dev/null &&
	./scripts/feeds install -p zltphone kmod-slic-spi-cs1 kmod-mt7621-pcm-raw slic-fxs >/dev/null)
grep -q '^CONFIG_PACKAGE_kmod-mt7621-pcm-raw=m' "$SDK/.config" 2>/dev/null || {
	make -C "$SDK" defconfig >/dev/null
	printf 'CONFIG_PACKAGE_kmod-slic-spi-cs1=m\nCONFIG_PACKAGE_kmod-mt7621-pcm-raw=m\n' >> "$SDK/.config"
	make -C "$SDK" defconfig >/dev/null
}
make -C "$SDK" package/kmod-slic-mt7621/clean >/dev/null
if ! make -C "$SDK" package/kmod-slic-mt7621/compile V=s > "$OUT/kmod-build.log" 2>&1; then
	grep -E 'error|Error' "$OUT/kmod-build.log" | head -n 20; exit 1
fi
for m in kmod-slic-spi-cs1/lib/modules/$KVER/slic_spi_cs1.ko \
	 kmod-mt7621-pcm-raw/lib/modules/$KVER/mt7621_pcm_raw.ko; do
	ko=$PKD/$m
	src=$HERE/kmod-slic-mt7621/src/$(basename "$ko" .ko).c
	[ -f "$ko" ] || { echo "missing $ko (see build/kmod-build.log)"; exit 1; }
	[ "$ko" -nt "$src" ] || { echo "stale $ko older than $src"; exit 1; }
	cp "$ko" "$OUT/"
	echo "built $(basename "$ko"): vermagic $(modinfo -F vermagic "$ko")"
done

# --- slic-fxs (slicctl + init script + config + slic-play + test audio) ---
[ -d "$HERE/slicctl/vpapi" ] || { echo "run slicctl/fetch-vpapi.sh first"; exit 1; }
[ -f "$HERE/slicctl/stock_profiles.c" ] || { echo "generate slicctl/stock_profiles.c with tools/extract_profiles.py"; exit 1; }
grep -q '^CONFIG_PACKAGE_slic-fxs=m' "$SDK/.config" || {
	echo 'CONFIG_PACKAGE_slic-fxs=m' >> "$SDK/.config"
	make -C "$SDK" defconfig >/dev/null
}
make -C "$SDK" package/slic-fxs/clean >/dev/null
if ! make -C "$SDK" package/slic-fxs/compile V=s > "$OUT/slic-fxs-build.log" 2>&1; then
	grep -E 'error|Error' "$OUT/slic-fxs-build.log" | head -n 20; exit 1
fi

# --- collect installable packages ---
rm -f "$OUT"/*.apk
for p in kmod-slic-spi-cs1 kmod-mt7621-pcm-raw slic-fxs; do
	apk=$(find "$SDK/bin" -name "$p-[0-9]*.apk" -newer "$HERE/build.sh" | head -n 1)
	[ -n "$apk" ] || apk=$(ls -t $(find "$SDK/bin" -name "$p-[0-9]*.apk") | head -n 1)
	[ -n "$apk" ] || { echo "no package built for $p"; exit 1; }
	cp "$apk" "$OUT/"
	echo "package $(basename "$apk")"
done
echo "install on the router:"
echo "  scp -O $OUT/*.apk root@ROUTER:/tmp/ && ssh root@ROUTER 'apk add --allow-untrusted /tmp/*slic*.apk /tmp/kmod-mt7621-pcm-raw*.apk'"
